const premiumFor = (quote: QuoteStep): number => {
  const policyBase = quote.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
};

const resultOf = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: premiumFor(step) };
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(resultOf),
});
